#!/bin/bash
# REDAXO Multi-Instances – container entrypoint
# Generated by the REDAXO Multi-Instances VS Code extension.
#
# Environment (all optional):
#   APACHE_DOCUMENT_ROOT   document root inside the container (default /var/www/html/public)
#   HOST_UID / HOST_GID    map www-data to the host user (Linux bind mounts)
#   XDEBUG_ENABLED         1 = load Xdebug (mode debug,develop, trigger based)
#   MAIL_HOST / MAIL_PORT  SMTP target for PHP mail() (default: shared Mailpit)
#   REDAXO_AUTO_INSTALL    1 = download + install REDAXO when the document root is empty
#   REDAXO_VERSION         REDAXO release to download (e.g. 5.21.6)
#   REDAXO_DOWNLOAD_URL    explicit download URL (overrides REDAXO_VERSION)
#   REDAXO_SERVER, REDAXO_SERVERNAME, REDAXO_ERROR_EMAIL, REDAXO_LANG, REDAXO_TIMEZONE
#   REDAXO_DB_HOST, REDAXO_DB_NAME, REDAXO_DB_LOGIN, REDAXO_DB_PASSWORD
#   REDAXO_ADMIN_USER, REDAXO_ADMIN_PASSWORD
set -euo pipefail

log() { echo >&2 "[redaxo-mi] $*"; }

DOCROOT="${APACHE_DOCUMENT_ROOT:-/var/www/html/public}"
export APACHE_DOCUMENT_ROOT="$DOCROOT"

# ---------------------------------------------------------------------------
# 1. File ownership: let www-data match the host user (only matters on Linux)
# ---------------------------------------------------------------------------
if [[ -n "${HOST_UID:-}" && "${HOST_UID}" != "0" && "$(id -u www-data)" != "${HOST_UID}" ]]; then
    log "Mapping www-data to UID ${HOST_UID}"
    if [[ -n "${HOST_GID:-}" && "${HOST_GID}" != "0" ]]; then
        groupmod -o -g "${HOST_GID}" www-data
    fi
    usermod -o -u "${HOST_UID}" www-data >/dev/null
fi

# ---------------------------------------------------------------------------
# 2. Runtime PHP configuration
# ---------------------------------------------------------------------------
if [[ "${XDEBUG_ENABLED:-0}" == "1" && -f /usr/local/etc/php/available/xdebug.ini ]]; then
    cp /usr/local/etc/php/available/xdebug.ini /usr/local/etc/php/conf.d/95-xdebug.ini
    log "Xdebug enabled (trigger mode, port 9003)"
else
    rm -f /usr/local/etc/php/conf.d/95-xdebug.ini
fi

cat > /etc/msmtprc <<EOF
account default
host ${MAIL_HOST:-redaxo-mi-mailpit}
port ${MAIL_PORT:-1025}
from ${MAIL_FROM:-redaxo@localhost}
auth off
tls off
EOF
chmod 0644 /etc/msmtprc

mkdir -p "$DOCROOT"

# ---------------------------------------------------------------------------
# 3. REDAXO download + unattended setup
# ---------------------------------------------------------------------------
as_www() { runuser -u www-data -- "$@"; }

docroot_is_empty() {
    [[ -z "$(find "$DOCROOT" -mindepth 1 -maxdepth 1 ! -name '.gitkeep' ! -name '.DS_Store' -print -quit)" ]]
}

if [[ "${REDAXO_AUTO_INSTALL:-0}" == "1" ]]; then
    if docroot_is_empty; then
        url="${REDAXO_DOWNLOAD_URL:-}"
        if [[ -z "$url" ]]; then
            version="${REDAXO_VERSION:-latest}"
            if [[ "$version" == "latest" ]]; then
                version="$(curl -fsSL https://api.github.com/repos/redaxo/core/releases/latest | sed -n 's/.*"tag_name": *"\([^"]*\)".*/\1/p' | head -n1)"
            fi
            url="https://github.com/redaxo/core/releases/download/${version}/redaxo_${version}.zip"
        fi
        log "Downloading REDAXO from ${url}"
        tmpzip="$(mktemp --suffix=.zip)"
        curl -fsSL --retry 3 -o "$tmpzip" "$url"
        unzip -oq "$tmpzip" -d "$DOCROOT"
        rm -f "$tmpzip"
        chown -R www-data:www-data "$DOCROOT"
        log "REDAXO files extracted to ${DOCROOT}"
    fi

    console="$DOCROOT/redaxo/bin/console"
    config="$DOCROOT/redaxo/data/core/config.yml"
    if [[ -f "$console" ]] && { [[ ! -f "$config" ]] || grep -qE '^setup:[[:space:]]*true' "$config"; }; then
        log "Running REDAXO setup"
        mkdir -p "$(dirname "$config")"
        [[ -f "$config" ]] || cp "$DOCROOT/redaxo/src/core/default.config.yml" "$config"
        chown -R www-data:www-data "$DOCROOT/redaxo/data" "$DOCROOT/redaxo/cache" 2>/dev/null || true

        tries=30
        until as_www php "$console" -q db:set-connection \
                --host="${REDAXO_DB_HOST:-db}" --database="${REDAXO_DB_NAME:-redaxo}" \
                --login="${REDAXO_DB_LOGIN:-redaxo}" --password="${REDAXO_DB_PASSWORD:-}" >/dev/null 2>&1; do
            tries=$((tries - 1))
            if (( tries <= 0 )); then
                log "ERROR: database is not reachable – REDAXO setup skipped"
                break
            fi
            sleep 2
        done

        if (( tries > 0 )); then
            args=(--agree-license --db-createdb=no --db-setup=normal --db-charset=utf8mb4
                "--db-host=${REDAXO_DB_HOST:-db}" "--db-name=${REDAXO_DB_NAME:-redaxo}"
                "--db-login=${REDAXO_DB_LOGIN:-redaxo}" "--db-password=${REDAXO_DB_PASSWORD:-}")
            [[ -n "${REDAXO_LANG:-}" ]] && args+=("--lang=${REDAXO_LANG}")
            [[ -n "${REDAXO_SERVER:-}" ]] && args+=("--server=${REDAXO_SERVER}")
            [[ -n "${REDAXO_SERVERNAME:-}" ]] && args+=("--servername=${REDAXO_SERVERNAME}")
            [[ -n "${REDAXO_ERROR_EMAIL:-}" ]] && args+=("--error-email=${REDAXO_ERROR_EMAIL}")
            [[ -n "${REDAXO_TIMEZONE:-}" ]] && args+=("--timezone=${REDAXO_TIMEZONE}")
            [[ -n "${REDAXO_ADMIN_USER:-}" ]] && args+=("--admin-username=${REDAXO_ADMIN_USER}")
            [[ -n "${REDAXO_ADMIN_PASSWORD:-}" ]] && args+=("--admin-password=${REDAXO_ADMIN_PASSWORD}")
            if as_www php "$console" setup:run -n "${args[@]}" > /tmp/redaxo-setup.log 2>&1; then
                log "REDAXO setup finished"
            else
                log "ERROR: REDAXO setup failed – open the backend to finish the setup manually"
                tail -n 20 /tmp/redaxo-setup.log >&2 || true
            fi
        fi
    fi
fi

# ---------------------------------------------------------------------------
# 3b. REDAXO 6 (Composer based, configured via environment variables)
#     REDAXO6_SOURCE=project  composer create-project redaxo/project (docroot public/)
#     REDAXO6_SOURCE=core     git clone redaxo/core (dev instance in project/, docroot project/public/)
# ---------------------------------------------------------------------------
as_composer() {
    runuser -u www-data -- env HOME=/tmp/composer-home COMPOSER_HOME=/tmp/composer-home \
        COMPOSER_CACHE_DIR=/var/cache/composer COMPOSER_NO_INTERACTION=1 "$@"
}

wait_for_database_url() {
    local tries=60
    # shellcheck disable=SC2016 # PHP code, expanded by PHP
    until php -r '$u = parse_url((string) getenv("DATABASE_URL"));
        new PDO(sprintf("mysql:host=%s;port=%d;dbname=%s", $u["host"], $u["port"] ?? 3306, ltrim($u["path"] ?? "", "/")),
            urldecode($u["user"] ?? ""), urldecode($u["pass"] ?? ""));' >/dev/null 2>&1; do
        tries=$((tries - 1))
        if (( tries <= 0 )); then
            return 1
        fi
        sleep 2
    done
}

if [[ -n "${REDAXO6_SOURCE:-}" ]]; then
    APP=/var/www/html
    mkdir -p /tmp/composer-home /var/cache/composer
    chown www-data:www-data /tmp/composer-home /var/cache/composer
    if [[ "$REDAXO6_SOURCE" == "core" ]]; then
        console="$APP/project/bin/console"
        marker="$APP/project/var/.redaxo-mi-installed"
    else
        console="$APP/bin/console"
        marker="$APP/var/.redaxo-mi-installed"
    fi

    if [[ ! -f "$APP/composer.json" ]]; then
        rm -rf /tmp/redaxo6
        if [[ "$REDAXO6_SOURCE" == "core" ]]; then
            log "Cloning redaxo/core (${REDAXO6_BRANCH:-6.x})"
            as_composer git clone --branch "${REDAXO6_BRANCH:-6.x}" https://github.com/redaxo/core.git /tmp/redaxo6
        else
            log "Creating REDAXO 6 project (redaxo/project:${REDAXO6_VERSION:-6.x-dev})"
            as_composer composer create-project --no-progress --no-install "redaxo/project:${REDAXO6_VERSION:-6.x-dev}" /tmp/redaxo6
        fi
        cp -a /tmp/redaxo6/. "$APP"/
        rm -rf /tmp/redaxo6
        chown -R www-data:www-data "$APP"
    fi
    if [[ ! -d "$APP/vendor" ]]; then
        log "Installing Composer dependencies"
        (cd "$APP" && as_composer composer install --no-progress) || log "ERROR: composer install failed"
    fi

    if [[ -f "$console" ]]; then
        if ! wait_for_database_url; then
            log "ERROR: database is not reachable – REDAXO 6 setup skipped"
        elif [[ ! -f "$marker" ]]; then
            log "Running REDAXO 6 setup"
            args=(--lang="${REDAXO_LANG:-de_de}")
            [[ -n "${REDAXO_ADMIN_USER:-}" ]] && args+=("--admin-username=${REDAXO_ADMIN_USER}")
            [[ -n "${REDAXO_ADMIN_PASSWORD:-}" ]] && args+=("--admin-password=${REDAXO_ADMIN_PASSWORD}")
            if as_composer php "$console" setup -n "${args[@]}" > /tmp/redaxo-setup.log 2>&1; then
                mkdir -p "$(dirname "$marker")"
                touch "$marker"
                chown www-data:www-data "$marker"
                log "REDAXO 6 setup finished"
            else
                log "ERROR: REDAXO 6 setup failed"
                tail -n 30 /tmp/redaxo-setup.log >&2 || true
            fi
        else
            # bring the database in line with the code (e.g. after git pull / composer update)
            as_composer php "$console" migrate -n >/tmp/redaxo-migrate.log 2>&1 \
                || { log "WARNING: console migrate failed"; tail -n 20 /tmp/redaxo-migrate.log >&2 || true; }
        fi
    fi
fi

# ---------------------------------------------------------------------------
# 4. Optional per-instance hook (./docker/custom-setup.sh on the host)
# ---------------------------------------------------------------------------
if [[ -x /usr/local/bin/custom-setup.sh ]]; then
    log "Running custom-setup.sh"
    /usr/local/bin/custom-setup.sh || log "WARNING: custom-setup.sh failed"
fi

log "Ready – document root ${DOCROOT}"
exec docker-php-entrypoint "$@"
